using System;
using System.Reflection;

// PROGRAM: Eksperimen Custom Attribute dan Inspeksi Metadata
[AttributeUsage(AttributeTargets.Property)]
public class AuditLogAttribute : Attribute
{
    public string Category { get; }
    public AuditLogAttribute(string category) => Category = category;
}

public class TransferRequest
{
    [AuditLog("FINANCIAL_CRITICAL")]
    public string AccountNumber { get; set; } = "123-456";

    [AuditLog("FINANCIAL_CRITICAL")]
    public decimal Amount { get; set; } = 500_000m;

    public string ClientDevice { get; set; } = "iPhone 15"; // Tidak diaudit
}

public class Program
{
    public static void Main()
    {
        Console.WriteLine("=== INSPEKSI ATRIBUT AUDIT VIA REFLECTION ===");
        var req = new TransferRequest();
        var props = typeof(TransferRequest).GetProperties();

        foreach (var p in props)
        {
            var auditAttr = p.GetCustomAttribute<AuditLogAttribute>();
            if (auditAttr != null)
            {
                object? val = p.GetValue(req);
                Console.WriteLine($"[AUDIT TRACKED] Properti: {p.Name,-15} | Kategori: {auditAttr.Category,-20} | Nilai: {val}");
            }
        }
    }
}

