using System;
using System.Reflection;
using System.Linq;
using System.Text;

public class ObjectInspector
{
    public static string InspectPublicProperties(object? target)
    {
        if (target == null) return "";

        var props = target.GetType().GetProperties(BindingFlags.Public | BindingFlags.Instance)
            .OrderBy(p => p.Name, StringComparer.Ordinal);

        var sb = new StringBuilder();
        foreach (var p in props)
        {
            object? val = p.GetValue(target);
            string valStr = val == null ? "null" : val.ToString()!;
            sb.Append($"{p.Name}={valStr};");
        }

        return sb.ToString();
    }

    public static void Main()
    {
        var data = new { B_Status = "Active", A_Id = 101 };
        Console.WriteLine(InspectPublicProperties(data));
    }
}
